import Foundation
public struct MultiLayerTireThermalState: Codable, Hashable, Sendable { public var treadC=24.0,carcassC=24.0,gasC=24.0,coldPressureKPa=206.8,pressureKPa=206.8,wearLife01=1.0,gripMultiplier=0.72; public init(){} }
public struct MultiLayerTireThermalSpec: Codable, Hashable, Sendable { public var treadCapacityJK=3650.0,carcassCapacityJK=15000.0,gasCapacityJK=850.0,treadCarcassWK=48.0,carcassGasWK=22.0,roadWK=80.0,optimalTreadC=88.0,coldReferenceC=24.0;public init(){} }
public enum MultiLayerTireThermalAuthority {
 public static func step(state:inout MultiLayerTireThermalState,spec:MultiLayerTireThermalSpec = .init(),slipPowerW:Double,verticalLoadN:Double,wheelOmega:Double,ambientC:Double,roadC:Double,dt:Double){let h=max(0,min(0.1,dt));let qTC=spec.treadCarcassWK*(state.treadC-state.carcassC),qCG=spec.carcassGasWK*(state.carcassC-state.gasC),qRoad=spec.roadWK*(state.treadC-roadC),qAir=(14+abs(wheelOmega)*0.12)*(state.treadC-ambientC);let flex=abs(wheelOmega)*max(0,verticalLoadN)*0.012;state.treadC += (max(0,slipPowerW)-qTC-qRoad-qAir)/spec.treadCapacityJK*h;state.carcassC += (qTC+flex-qCG)/spec.carcassCapacityJK*h;state.gasC += qCG/spec.gasCapacityJK*h;state.pressureKPa=state.coldPressureKPa*(state.gasC+273.15)/(spec.coldReferenceC+273.15);let d=state.treadC-spec.optimalTreadC;state.gripMultiplier=d<0 ? max(0.68,1+d/210) : max(0.52,1-d*d/3000);state.wearLife01=max(0,state.wearLife01-max(0,slipPowerW)/9000*(state.treadC>110 ? 2.2:1)*h*0.00004)}
}
